import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { motion } from 'framer-motion';
import styles from './AdminPanel.module.css';

// Данные марок и моделей
const brandModels = {
  "Rolls-Royce": ["Phantom", "Ghost", "Cullinan", "Wraith", "Dawn"],
  "Bentley": ["Continental GT", "Flying Spur", "Bentayga", "Mulsanne"],
  "Mercedes-Benz": ["S-Class", "E-Class", "C-Class", "GLS", "G-Class", "AMG GT", "Maybach S-Class"],
  "BMW": ["7 Series", "5 Series", "M5", "M8", "X7", "X5", "i7"],
  "Audi": ["A8", "A6", "Q8", "e-tron GT", "RS7", "RS Q8"],
  "Porsche": ["Panamera", "Taycan", "Cayenne", "911 Turbo S"],
  "Lexus": ["LS", "LX", "LC", "ES"],
  "Maserati": ["Quattroporte", "Ghibli", "Levante", "MC20"],
  "Aston Martin": ["DB11", "Vantage", "DBS", "DBX"],
  "Ferrari": ["SF90 Stradale", "Roma", "812 Superfast", "F8 Tributo"],
  "Lamborghini": ["Urus", "Huracán", "Aventador", "Revuelto"],
  "McLaren": ["720S", "Artura", "GT", "765LT"],
  "Range Rover": ["Sport", "Vogue", "Velar", "Evoque"],
  "Jaguar": ["XJ", "F-Pace", "I-Pace", "F-Type"],
};

// Список марок для быстрого поиска (ключи объекта)
const brandList = Object.keys(brandModels).sort();

// Типы кузова на русском
const bodyTypesRu = {
  "sedan": "Седан",
  "coupe": "Купе",
  "cabriolet": "Кабриолет",
  "wagon": "Универсал",
  "suv": "Внедорожник",
  "pickup": "Пикап",
  "limousine": "Лимузин",
  "hatchback": "Хэтчбек",
};

const AdminPanel = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [cars, setCars] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loading, setLoading] = useState(true);

  // Состояния формы
  const [showAddForm, setShowAddForm] = useState(false);
  const [newCar, setNewCar] = useState({
    brand: '',
    model: '',
    year: '',
    price: '',
    description: '',
    image_url: '',
    body_type: 'sedan',
    restyling: false,
  });
  const [uploading, setUploading] = useState(false);
  const [errors, setErrors] = useState({});

  // Управление изображениями
  const [selectedCarId, setSelectedCarId] = useState(null);
  const [newImageUrl, setNewImageUrl] = useState('');
  const [carImages, setCarImages] = useState([]);

  const fetchData = async () => {
    try {
      const [statsRes, usersRes, carsRes, tdRes] = await Promise.all([
        api.get('/admin/stats'),
        api.get('/admin/users'),
        api.get('/cars/'),
        api.get('/testdrives/all'),
      ]);
      setStats(statsRes.data);
      setUsers(usersRes.data);
      setCars(carsRes.data);
      setTestDrives(tdRes.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  // Валидация формы
  const validateForm = () => {
    const newErrors = {};
    if (!newCar.brand.trim()) newErrors.brand = 'Выберите марку';
    if (!newCar.model.trim()) newErrors.model = 'Выберите модель';
    // Проверка, что модель соответствует выбранной марке (если марка выбрана)
    if (newCar.brand && brandModels[newCar.brand] && !brandModels[newCar.brand].includes(newCar.model)) {
      newErrors.model = 'Модель не соответствует выбранной марке';
    }
    if (!newCar.year || parseInt(newCar.year) < 1900 || parseInt(newCar.year) > 2030) {
      newErrors.year = 'Год должен быть между 1900 и 2030';
    }
    if (!newCar.price || parseFloat(newCar.price) <= 0) {
      newErrors.price = 'Цена должна быть положительным числом';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Загрузка файла
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/cars/upload_image', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setNewCar(prev => ({ ...prev, image_url: res.data.image_url }));
    } catch (err) {
      alert('Ошибка загрузки файла');
    } finally {
      setUploading(false);
    }
  };

  // Добавление автомобиля
  const handleAddCar = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;
    try {
      const carData = {
        ...newCar,
        year: parseInt(newCar.year),
        price: parseFloat(newCar.price),
        restyling: newCar.restyling,
      };
      const res = await api.post('/cars/', carData);
      setCars(prev => [...prev, res.data]);
      setShowAddForm(false);
      setNewCar({ brand: '', model: '', year: '', price: '', description: '', image_url: '', body_type: 'sedan', restyling: false });
      setErrors({});
    } catch (err) {
      alert('Ошибка добавления автомобиля');
    }
  };

  // При смене марки сбрасываем модель, если она не соответствует новой марке
  const handleBrandChange = (brand) => {
    setNewCar(prev => ({
      ...prev,
      brand,
      model: brandModels[brand]?.includes(prev.model) ? prev.model : '',
    }));
    setErrors({});
  };

  const handleDeleteUser = async (userId) => {
    if (window.confirm('Удалить пользователя?')) {
      await api.delete(`/admin/users/${userId}`);
      setUsers(users.filter(u => u.id !== userId));
    }
  };

  const handleRoleChange = async (userId, newRole) => {
    await api.put(`/admin/users/${userId}/role`, { role: newRole });
    setUsers(users.map(u => u.id === userId ? { ...u, role: newRole } : u));
  };

  const handleDeleteCar = async (carId) => {
    if (window.confirm('Удалить автомобиль?')) {
      await api.delete(`/cars/${carId}`);
      setCars(cars.filter(c => c.id !== carId));
    }
  };

  // Управление изображениями
  const openCarImages = (carId) => {
    setSelectedCarId(carId);
    const car = cars.find(c => c.id === carId);
    setCarImages(car?.images || []);
    setNewImageUrl('');
  };

  const handleAddImage = async () => {
    if (!newImageUrl.trim()) return;
    try {
      const res = await api.post(`/cars/${selectedCarId}/images`, { image_url: newImageUrl });
      setCarImages(prev => [...prev, res.data]);
      setNewImageUrl('');
    } catch (err) {
      alert('Ошибка добавления изображения');
    }
  };

  const handleDeleteImage = async (imageId) => {
    try {
      await api.delete(`/cars/images/${imageId}`);
      setCarImages(prev => prev.filter(img => img.id !== imageId));
    } catch (err) {
      alert('Ошибка удаления изображения');
    }
  };

  if (loading) return <div className={styles.loading}>Загрузка...</div>;

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 className={styles.title}>Админ-панель</h2>
      <div className={styles.tabs}>
        {['dashboard', 'users', 'cars', 'testdrives'].map(tab => (
          <button
            key={tab}
            className={`${styles.tab} ${activeTab === tab ? styles.active : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            {tab === 'testdrives' ? 'Заявки' : tab === 'cars' ? 'Автомобили' : tab === 'users' ? 'Пользователи' : 'Дашборд'}
          </button>
        ))}
      </div>

      <div className={styles.content}>
        {activeTab === 'dashboard' && stats && (
          <div className={styles.dashboard}>
            <div className={styles.statCard}><h3>Пользователи</h3><p>{stats.total_users}</p></div>
            <div className={styles.statCard}><h3>Автомобили</h3><p>{stats.total_cars}</p></div>
            <div className={styles.statCard}><h3>Заявки на тест-драйв</h3><p>{stats.total_testdrives}</p></div>
            <div className={styles.statCard}><h3>Покупки</h3><p>{stats.total_purchases}</p></div>
          </div>
        )}

        {activeTab === 'users' && (
          <div>
            <table className={styles.table}>
              <thead>
                <tr><th>ID</th><th>Email</th><th>Имя</th><th>Роль</th><th>Действия</th></tr>
              </thead>
              <tbody>
                {users.map(u => (
                  <tr key={u.id}>
                    <td>{u.id}</td><td>{u.email}</td><td>{u.full_name}</td>
                    <td>
                      <select value={u.role} onChange={(e) => handleRoleChange(u.id, e.target.value)} disabled={u.id === user.id}>
                        <option value="user">user</option>
                        <option value="admin">admin</option>
                      </select>
                    </td>
                    <td>
                      <button onClick={() => handleDeleteUser(u.id)} disabled={u.id === user.id || u.role === 'admin'} className={styles.deleteBtn}>
                        Удалить
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'cars' && (
          <div>
            <button className={styles.addBtn} onClick={() => setShowAddForm(!showAddForm)}>
              {showAddForm ? 'Отменить' : 'Добавить автомобиль'}
            </button>

            {showAddForm && (
              <form onSubmit={handleAddCar} style={{
                background: 'rgba(255,255,255,0.7)',
                backdropFilter: 'blur(10px)',
                borderRadius: '20px',
                padding: '2rem',
                boxShadow: '0 15px 35px rgba(74,20,140,0.15)',
                border: '1px solid rgba(255,255,255,0.5)',
                marginBottom: '1.5rem',
                display: 'flex',
                flexWrap: 'wrap',
                gap: '1.2rem',
              }}>
                <h3 style={{ width: '100%', fontFamily: 'Playfair Display', fontSize: '1.5rem', marginBottom: '0' }}>Новый автомобиль</h3>

                {/* Марка */}
                <div style={{ flex: '1 1 280px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Марка</label>
                  <input
                    type="text"
                    placeholder="Выберите марку"
                    list="brandList"
                    value={newCar.brand}
                    onChange={(e) => handleBrandChange(e.target.value)}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: errors.brand ? '2px solid #D32F2F' : '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                    }}
                  />
                  <datalist id="brandList">
                    {brandList.map(b => <option key={b} value={b} />)}
                  </datalist>
                  {errors.brand && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.brand}</span>}
                </div>

                {/* Модель – зависит от марки */}
                <div style={{ flex: '1 1 280px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Модель</label>
                  <select
                    value={newCar.model}
                    onChange={(e) => setNewCar({ ...newCar, model: e.target.value })}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: errors.model ? '2px solid #D32F2F' : '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                    }}
                    disabled={!newCar.brand || !brandModels[newCar.brand]}
                  >
                    <option value="">{newCar.brand ? 'Выберите модель' : 'Сначала выберите марку'}</option>
                    {newCar.brand && brandModels[newCar.brand]?.map(m => (
                      <option key={m} value={m}>{m}</option>
                    ))}
                  </select>
                  {errors.model && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.model}</span>}
                </div>

                {/* Год */}
                <div style={{ flex: '1 1 120px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Год</label>
                  <input
                    type="number"
                    placeholder="2025"
                    value={newCar.year}
                    onChange={(e) => setNewCar({ ...newCar, year: e.target.value })}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: errors.year ? '2px solid #D32F2F' : '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                    }}
                  />
                  {errors.year && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.year}</span>}
                </div>

                {/* Цена */}
                <div style={{ flex: '1 1 160px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Цена (₽)</label>
                  <input
                    type="number"
                    placeholder="10000000"
                    value={newCar.price}
                    onChange={(e) => setNewCar({ ...newCar, price: e.target.value })}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: errors.price ? '2px solid #D32F2F' : '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                    }}
                  />
                  {errors.price && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.price}</span>}
                </div>

                {/* Тип кузова на русском */}
                <div style={{ flex: '1 1 150px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Кузов</label>
                  <select
                    value={newCar.body_type}
                    onChange={(e) => setNewCar({ ...newCar, body_type: e.target.value })}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                    }}
                  >
                    {Object.entries(bodyTypesRu).map(([key, label]) => (
                      <option key={key} value={key}>{label}</option>
                    ))}
                  </select>
                </div>

                {/* Описание */}
                <div style={{ flex: '1 1 100%' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Описание</label>
                  <textarea
                    placeholder="Краткое описание автомобиля"
                    value={newCar.description}
                    onChange={(e) => setNewCar({ ...newCar, description: e.target.value })}
                    rows={3}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                      resize: 'vertical',
                    }}
                  />
                </div>

                {/* Загрузка своего фото */}
                <div style={{ flex: '1 1 250px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Фото (загрузить с устройства)</label>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleFileUpload}
                    style={{ display: 'block' }}
                  />
                  {uploading && <span style={{ fontSize: '0.9rem', color: '#7B1FA2' }}>Загрузка...</span>}
                </div>

                {/* URL изображения (альтернатива) */}
                <div style={{ flex: '1 1 250px' }}>
                  <label style={{ display: 'block', fontWeight: 600, marginBottom: '0.3rem' }}>Или URL изображения</label>
                  <input
                    type="text"
                    placeholder="https://..."
                    value={newCar.image_url}
                    onChange={(e) => setNewCar({ ...newCar, image_url: e.target.value })}
                    style={{
                      width: '100%',
                      padding: '0.7rem',
                      borderRadius: '12px',
                      border: '1px solid rgba(74,20,140,0.2)',
                      fontFamily: 'inherit',
                      background: 'white',
                    }}
                  />
                </div>

                {/* Рестайлинг */}
                <div style={{ flex: '1 1 100%', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                  <input
                    type="checkbox"
                    id="restyling"
                    checked={newCar.restyling}
                    onChange={(e) => setNewCar({ ...newCar, restyling: e.target.checked })}
                  />
                  <label htmlFor="restyling" style={{ fontWeight: 600 }}>Рестайлинг</label>
                </div>

                <button type="submit" className={styles.addBtn} style={{ flex: '1 1 150px', alignSelf: 'flex-end' }}>
                  Добавить
                </button>
              </form>
            )}

            <table className={styles.table}>
              <thead>
                <tr><th>ID</th><th>Марка</th><th>Модель</th><th>Цена</th><th>Действия</th></tr>
              </thead>
              <tbody>
                {cars.map(car => (
                  <tr key={car.id}>
                    <td>{car.id}</td><td>{car.brand}</td><td>{car.model}</td>
                    <td>{car.price.toLocaleString()} ₽</td>
                    <td>
                      <button className={styles.addBtn} style={{ marginRight: '0.5rem', padding: '0.4rem 1rem' }} onClick={() => openCarImages(car.id)}>Фото</button>
                      <button className={styles.deleteBtn} onClick={() => handleDeleteCar(car.id)}>Удалить</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Панель управления изображениями */}
            {selectedCarId && (
              <div style={{ marginTop: '2rem', background: 'rgba(255,255,255,0.7)', backdropFilter: 'blur(10px)', padding: '1rem', borderRadius: '16px' }}>
                <h3>Управление изображениями (авто ID: {selectedCarId})</h3>
                <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
                  <input
                    type="text"
                    placeholder="URL изображения"
                    value={newImageUrl}
                    onChange={(e) => setNewImageUrl(e.target.value)}
                    style={{ flex: 1, padding: '0.5rem', borderRadius: '8px', border: '1px solid #ccc' }}
                  />
                  <button onClick={handleAddImage} className={styles.addBtn}>Добавить</button>
                </div>
                <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
                  {carImages.map(img => (
                    <div key={img.id} style={{ position: 'relative', width: '100px', height: '80px' }}>
                      <img src={img.image_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '6px' }} />
                      <button
                        onClick={() => handleDeleteImage(img.id)}
                        style={{
                          position: 'absolute', top: 2, right: 2,
                          background: 'red', color: 'white', border: 'none', borderRadius: '50%',
                          width: '20px', height: '20px', cursor: 'pointer', fontSize: '12px'
                        }}
                      >×</button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'testdrives' && (
          <div>
            <table className={styles.table}>
              <thead>
                <tr><th>ID</th><th>Пользователь</th><th>Авто ID</th><th>Дата</th><th>Статус</th></tr>
              </thead>
              <tbody>
                {testDrives.map(td => (
                  <tr key={td.id}>
                    <td>{td.id}</td><td>{td.user_id}</td><td>{td.car_id}</td>
                    <td>{new Date(td.preferred_date).toLocaleString()}</td><td>{td.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default AdminPanel;
